(function(root){'use strict';
const MINUTE=60000;
function batches(state,now,seen={}){const parties=Object.values(state?.parties||{}).filter(p=>Number.isFinite(p.at)&&p.at<=now).sort((a,b)=>a.at-b.at),groups=[];for(const p of parties){let g=groups[groups.length-1];if(!g||p.at-g[0].at>MINUTE)groups.push(g=[]);g.push(p);}const result=[];for(const p of parties)if(now-p.at<=MINUTE&&!seen['beep:'+p.id])result.push({kind:'beep',rows:[{key:'beep:'+p.id,table:[p.primary,...(Array.isArray(p.secondary)?p.secondary:[])].join(' + '),server:(state.shifts?.[p.shift]?.rows||[]).find(r=>r.id===p.rowId)?.server||'the assigned server'}]});for(const group of groups)for(const [kind,delay]of [['check',3*MINUTE]]){const due=group[group.length-1].at+delay;if(now<due||now-due>5*MINUTE)continue;const rows=group.filter(p=>!seen[kind+':'+p.id]).map(p=>({key:kind+':'+p.id,table:[p.primary,...(Array.isArray(p.secondary)?p.secondary:[])].join(' + '),server:(state.shifts?.[p.shift]?.rows||[]).find(r=>r.id===p.rowId)?.server||'the assigned server'}));if(rows.length)result.push({kind,rows});}return result;}
class TableAlerts{
 constructor(options){this.options=options;this.seen={};try{this.seen=JSON.parse(localStorage.getItem('fz_table_alert_ack')||'{}')||{};}catch(_){}this.timer=setInterval(()=>this.check(),5000);document.addEventListener('visibilitychange',()=>this.check());}
 check(){if(document.hidden||document.querySelector('dialog[open]'))return;const now=this.options.now(),items=batches(this.options.state(),now,this.seen);if(!items.length)return;const dialog=document.createElement('dialog');dialog.id='tableServiceAlert';const title=document.createElement('h2');title.textContent='TABLE SERVICE REMINDER';dialog.appendChild(title);for(const item of items){const heading=document.createElement('h3');heading.textContent=item.kind==='beep'?'Please beep the server':'Please check these tables';dialog.appendChild(heading);for(const row of item.rows){const p=document.createElement('p');p.textContent=item.kind==='beep'?'Don’t forget to beep '+row.server+' — Table '+row.table+'.':'Please check table '+row.table+' — '+row.server+'. Has the party been served?';dialog.appendChild(p);}}const button=document.createElement('button');button.className='primary full';button.textContent='ACKNOWLEDGE';dialog.appendChild(button);const done=()=>{for(const item of items)for(const row of item.rows)this.seen[row.key]=now;for(const key of Object.keys(this.seen))if(now-this.seen[key]>86400000)delete this.seen[key];try{localStorage.setItem('fz_table_alert_ack',JSON.stringify(this.seen));}catch(_){}dialog.close();dialog.remove();};button.onclick=done;dialog.addEventListener('cancel',e=>{e.preventDefault();done();});document.body.appendChild(dialog);dialog.showModal();this.options.sound?.();}
}
root.TableAlerts=TableAlerts;if(typeof module!=='undefined')module.exports={batches};
})(globalThis);
